"use client";
import React, { useState } from "react";
import { ShieldCheck, Cpu, Layers, Zap, Info, ChevronRight, Activity, Beaker } from "lucide-react";

const qualityMatrix = {
  footwear: [
    { id: "og", name: "OG / Surplus", tier: "Lvl 01: Authentic", accuracy: "100%", detail: "Genuine production excess. The gold standard. Original factory materials and assembly.", tech: ["Official NFC", "Retail Materials", "Full QC"] },
    { id: "ua", name: "UA (Unauthorized)", tier: "Lvl 02: High-Spec", accuracy: "98%", detail: "Produced using original molds and factory blueprints. Virtually identical to retail pairs.", tech: ["Original Molds", "Precision Stitching"] },
    { id: "semi-ua", name: "Semi-UA", tier: "Lvl 03: Performance", accuracy: "92%", detail: "High-grade materials that match retail texture, but with minor variances in internal cushioning.", tech: ["Premium Leather", "Retail Silhouette"] },
    { id: "7a", name: "7A Grade", tier: "Lvl 04: Visual", accuracy: "85%", detail: "Focused on aesthetic 1:1. Uses high-quality synthetic blends rather than authentic animal hides.", tech: ["Visual 1:1", "Durable Build"] },
    { id: "6a", name: "6A Grade", tier: "Lvl 05: Standard", accuracy: "75%", detail: "Entry-level replica. Correct colors and shape, but materials are standard market grade.", tech: ["Standard Comfort", "High Value"] },
    { id: "5a", name: "5A Grade", tier: "Lvl 06: Budget", accuracy: "60%", detail: "Budget-focused. Ideal for casual aesthetics where material precision isn't the priority.", tech: ["Economy Build", "Basic Materials"] },
  ],
  watches: [
    { id: "superclone", name: "Super Clone", tier: "Lvl 01: Master", accuracy: "99%", detail: "904L Steel with cloned Swiss movements. Weight and GMT sweep are indistinguishable.", tech: ["904L Steel", "3235 Clone"] },
    { id: "aaa", name: "AAA Grade", tier: "Lvl 02: Reliable", accuracy: "88%", detail: "Automatic Miyota movements with sapphire crystal. The standard for mid-market luxury.", tech: ["Sapphire Glass", "Automatic"] },
  ]
};

export default function QualityProtocolPage() {
  const [activeCat, setActiveCat] = useState<keyof typeof qualityMatrix>("footwear");

  return (
    <div className="bg-[#050505] text-[#f0f0f0] min-h-screen pb-32 selection:bg-brand selection:text-black">
      
      {/* 1. NEURAL HEADER */}
      <header className="pt-24 pb-16 px-6 max-w-7xl mx-auto flex flex-col items-center text-center">
        <div className="flex items-center gap-2 mb-8 px-4 py-1.5 rounded-full bg-brand/10 border border-brand/20">
          <Activity size={12} className="text-brand animate-pulse" />
          <span className="text-[9px] font-black uppercase tracking-[0.5em] text-brand">Quality Protocol v2.6</span>
        </div>
        <h1 className="text-7xl md:text-[10rem] font-black uppercase italic tracking-tighter leading-[0.7] mb-8">
          Tier <br /> <span className="opacity-10 italic">Intelligence</span>
        </h1>
        <p className="max-w-xl text-[11px] font-bold uppercase leading-relaxed opacity-40 tracking-widest italic">
          Decoding the manufacturing matrix. We classify global production into six distinct levels of technical accuracy.
        </p>
      </header>

      {/* 2. CATEGORY SELECTOR (Neural Pill) */}
      <nav className="flex justify-center mb-20">
        <div className="bg-[#0f0f0f] p-1.5 rounded-full border border-white/5 flex gap-1 shadow-2xl">
          {Object.keys(qualityMatrix).map((cat) => (
            <button
              key={cat}
              onClick={() => setActiveCat(cat as any)}
              className={`px-10 py-4 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                activeCat === cat ? "bg-brand text-black shadow-[0_0_30px_rgba(var(--brand-rgb),0.3)]" : "opacity-30 hover:opacity-100"
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </nav>

      {/* 3. THE PROTOCOL LIST (The Architect Design) */}
      <main className="max-w-6xl mx-auto px-6 space-y-6">
        {qualityMatrix[activeCat].map((item, i) => (
          <div 
            key={item.id}
            className="group relative bg-[#0a0a0a] border border-white/5 rounded-[2.5rem] p-8 md:p-12 hover:border-brand/50 transition-all duration-700 flex flex-col md:flex-row gap-10 items-center overflow-hidden"
          >
            {/* Background Texture */}
            <div className="absolute right-10 top-1/2 -translate-y-1/2 text-[12rem] font-black italic opacity-[0.02] group-hover:opacity-[0.05] transition-opacity pointer-events-none">
              {item.accuracy}
            </div>

            {/* Left: Accuracy Meter */}
            <div className="flex flex-col items-center justify-center shrink-0">
              <div className="relative h-24 w-24 flex items-center justify-center">
                 <svg className="absolute inset-0 h-full w-full rotate-[-90deg]">
                    <circle cx="48" cy="48" r="44" stroke="currentColor" strokeWidth="2" fill="transparent" className="text-white/5" />
                    <circle cx="48" cy="48" r="44" stroke="currentColor" strokeWidth="2" fill="transparent" className="text-brand" strokeDasharray="276" strokeDashoffset={276 - (276 * parseInt(item.accuracy)) / 100} />
                 </svg>
                 <span className="text-xl font-black italic">{item.accuracy}</span>
              </div>
              <p className="text-[8px] font-black uppercase tracking-widest mt-4 opacity-30">Accuracy</p>
            </div>

            {/* Center: Content */}
            <div className="flex-1 space-y-4 text-center md:text-left">
              <div>
                <span className="text-brand text-[9px] font-black uppercase tracking-[0.4em]">{item.tier}</span>
                <h3 className="text-4xl md:text-5xl font-black uppercase italic tracking-tighter mt-1">{item.name}</h3>
              </div>
              <p className="text-[12px] font-medium opacity-50 max-w-lg leading-relaxed">{item.detail}</p>
            </div>

            {/* Right: Specs Tags */}
            <div className="grid grid-cols-1 gap-2 shrink-0">
              {item.tech.map((t) => (
                <div key={t} className="flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full border border-white/5">
                  <div className="h-1 w-1 rounded-full bg-brand" />
                  <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{t}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </main>

      {/* 4. THE SURPLUS TRUTH (Protocol Card) */}
      <section className="max-w-6xl mx-auto px-6 mt-20">
        <div className="bg-foreground text-background rounded-[3.5rem] p-12 md:p-20 relative overflow-hidden group">
          <div className="absolute right-0 top-0 p-10 opacity-5 group-hover:rotate-180 transition-transform duration-1000">
             <Beaker size={400} />
          </div>
          <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-16">
            <div className="space-y-6">
              <h2 className="text-5xl md:text-8xl font-black uppercase italic tracking-tighter leading-[0.8]">
                Factory <br /> <span className="text-brand">Surplus</span>
              </h2>
              <div className="h-[2px] w-24 bg-brand" />
            </div>
            <div className="space-y-6">
              <p className="text-xl font-bold uppercase italic leading-tight">
                This is not a replica. Surplus is the byproduct of official mass-production. Authentic materials, authentic assembly, secondary market pricing.
              </p>
              <div className="pt-6 flex gap-8 border-t border-background/10">
                <div>
                  <p className="text-[8px] font-black uppercase tracking-widest opacity-40 mb-1">Status</p>
                  <p className="text-lg font-black italic">100% Genuine</p>
                </div>
                <div>
                  <p className="text-[8px] font-black uppercase tracking-widest opacity-40 mb-1">Origin</p>
                  <p className="text-lg font-black italic">Tier-1 Factory</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}